exercise.referenceSolution:
struct Source { int value; };
class View { const Source& source_; public: explicit View(const Source& source) : source_(source) {} int read() const { return source_.value; } };
int solve(int a,int b) { Source source{a}; View view{source}; source.value=b; return view.read(); }
